INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-004-59', 'p0127', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '往者季漢分崩，九土顛覆，劉備、孫權乘間作禍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-60', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '暹、奉不能奉王法，各出奔，寇徐、揚閒，為劉備所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-61', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '趙衢等舉義兵討超，超走漢中從張魯，後奔劉備，死於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-62', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '先是，太祖遣劉備詣徐州拒袁術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-63', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紹渡河，壁延津南，使劉備、文醜挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-64', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '劉備奔表，表厚待之，然不能用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-65', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋曰：太祖之始征柳城，劉備說表使襲許，表不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-66', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '以人臣而拒人主，逆也；以新造之楚而禦國家，其勢弗當也；以劉備而敵曹公，又弗當也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-67', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」巽曰：「誠以劉備不足禦曹公乎，則雖保楚之地，不足以自存也；誠以劉備足禦曹公乎，則備不為將軍下也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-68', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '文帝時為侍中，太和中卒，巽在荊州，目龐統為半英雄，證裴潛終以清行顯；統遂附劉備，見待次於諸葛亮，潛位至尚書令，並有名德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-006-69', 'p0127', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '漢晉春秋曰：王威說劉琮曰：「曹操得將軍旣降，劉備已走，必懈弛無備，輕行單進；若給威奇兵數千，徼之於險，操可獲也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-70', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術生年已來，不聞天下有劉備，備乃舉兵與術對戰；術憑將軍威靈，得以破備，其功三也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-71', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建安三年，布復叛為術，遣高順攻劉備於沛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-72', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '九州春秋曰：初，布騎將侯成遣客牧馬十五匹，客悉驅馬去，向沛城，欲歸劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-73', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '劉備進曰：「明公不見布之事丁建陽及董太師乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-74', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」布縛急，謂劉備曰：「玄德，卿為坐客，我為執虜，不能一言以相寬乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-007-75', 'p0127', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '後許汜與劉備並在荊州牧劉表坐，表與備共論天下人，汜曰：「陳元龍湖海之士，豪氣不除。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-76', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '二十三年，劉備軍陽平關，淵率諸將拒之，相守連年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-77', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖與袁紹乆相持於官渡，紹遣劉備徇㶏彊諸縣，多舉衆應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-78', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '仁曰：「南方以大軍方有目前急，其勢不能相救，劉備以彊兵臨之，其背叛固宜也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-79', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '從征荊州，追劉備於長坂，獲其二女輜重，收其散卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-80', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '劉備遣將吳蘭屯下辯，太祖遣曹洪征之，以休為騎都尉，參洪軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-81', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '以偏將軍將兵擊劉備別將於下辯，破之，拜中堅將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-82', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '以真為征蜀護軍，督徐晃等破劉備別將高詳於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-009-83', 'p0127', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '尚奏：「劉備別軍在上庸，山道險難，彼不我虞，若以奇兵潛行，出其不意，則獨克之勢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-84', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '權以露布於蜀，劉備聞之，曰：「老賊不死，禍亂未已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-85', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '」比行，布以敗劉備，而臧霸等應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-86', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '魏武後克平張魯，蜀中一日數十驚，劉備雖斬之而不能止，由不用劉曄之計，以失席卷之會，斤石旣差，悔無所及，即亦此事之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-010-87', 'p0127', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '吳、蜀雖蕞爾小國，依岨山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陸議見兵勢，據險守要，汎舟江湖，皆難卒謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-011-88', 'p0127', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '劉備之為豫州，舉渙茂才。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-011-89', 'p0127', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '布初與劉備和親，後離隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-011-90', 'p0127', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時有傳劉備死者，羣臣皆賀；渙以甞為備舉吏，獨不賀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-012-91', 'p0127', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '在郡六年，劉備表融領青州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-012-92', 'p0127', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '魏書曰：自劉備叛後，東南多變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-013-93', 'p0127', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '初，建安末，孫權始遣使稱藩，而與劉備交兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-94', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '徐庶母為曹公所得，劉備乃遣庶歸，欲為天下者恕人子之情也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-95', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備失徐州，來歸太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-96', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖征荊州，劉備奔吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-97', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備有英名，關羽、張飛皆萬人敵也，權必資之以禦我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-98', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」　魏書曰：劉備來奔，以為豫州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-99', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」　傅子曰：初，劉備來降，太祖以客禮待之，使為豫州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-100', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '傅子曰：太祖欲速征劉備，議者懼軍出，袁紹擊其後，進不得戰而退失所據。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-101', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖將征袁尚及三郡烏丸，諸下多懼劉表使劉備襲許以討太祖，嘉曰：「公雖威震天下，胡恃其遠，必不設備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-102', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-103', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備，人傑也，有度而遲，得蜀日淺，蜀人未恃也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-104', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '其後孟達去劉備歸文帝，論者多稱有樂毅之量。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-105', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '詔問羣臣令料劉備當為關羽出報吳不。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-106', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '權將陸議大敗劉備，殺其兵八萬餘人，備僅以身免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-014-107', 'p0127', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備、孫權，外親內踈，關羽得志，權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-015-108', 'p0127', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖將拔漢中守，恐劉備北取武都氐以逼關中，問旣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-015-109', 'p0127', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太祖征劉備，先遣逵至斜谷觀形勢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-110', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '今天子在許，公遠北征，若劉表遣劉備襲許，據之以號令四方，公之勢去矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-111', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-112', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又討劉備臨沮長杜普、旌陽長梁大，皆大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-113', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '劉備以徐州叛，太祖東征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-114', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '至陽平，魯降，太祖還，留郃與夏侯淵等守漢中，拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-115', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '劉備屯陽平，郃屯廣石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-116', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '魏略曰：淵雖為都督，劉備憚郃而易淵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-117', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '淵司馬郭淮乃令衆曰：「張將軍，國家名將，劉備所憚；今日事急，非張將軍不能安也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-118', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖遂自至漢中，劉備保高山不敢戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-119', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破劉備，又從破顏良，拔白馬，進至延津，破文醜，拜偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-120', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖還鄴，留晃與夏侯淵拒劉備於陽平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-121', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '劉備欲斷絕外內，以取漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-017-122', 'p0127', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '與夏侯尚討劉備於上庸，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-123', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉表使劉備北侵，至葉，太祖遣典從夏侯惇拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-124', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-125', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖語劉備，令語霸送二人首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-126', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '授聘兵，使與曹純追討劉備於長阪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-127', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '汝劉備庸才耳，豈能敵邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-018-128', 'p0127', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '」斆曰：「蜀漢絕遠，劉備嘗用之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-019-129', 'p0127', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '」魏略曰：太祖在漢中，而劉備栖於山頭，使劉封下挑戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-130', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '雄略冠時，智謀出世，摧袁氏於官渡，驅孫權於江外，逐劉備於隴右，破烏丸於白登，其餘梟夷蕩定者，往往如神，不可勝計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-131', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '魏武以十三年征荊州，劉備却後數年方入蜀，備身未嘗涉於關、隴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-132', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又典略載太祖初征荊州，使瑀作書與劉備，及征馬超，又使瑀作書與韓遂，此二書今具存。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-021-133', 'p0127', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '今以海內之兵，百勝之威，而孫權負險於吳，劉備不賔於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-022-134', 'p0127', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '劉備臨豫州，辟羣為別駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-022-135', 'p0127', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '昔劉備自成都至白水，多作傳舍，興費人役，太祖知其疲民也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-023-136', 'p0127', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '夏侯淵為劉備所沒，軍喪元帥，將士失色。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-023-137', 'p0127', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太祖問潛曰：「卿前與劉備俱在荊州，卿以備才略何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-025-138', 'p0127', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '會劉備遣張飛、馬超等從沮道趣下辯，而氐雷定等七部萬餘落反應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-025-139', 'p0127', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '及劉備取漢中以逼下辯，太祖以武都孤遠，欲移之，恐吏民戀土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-026-140', 'p0127', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '劉備之奔公孫瓚也，豫時年少，自託於備，備甚奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-026-141', 'p0127', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太祖還，留征西將軍夏侯淵拒劉備，以淮為淵司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-028-142', 'p0127', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '事成，可得天下；不成，退保蜀漢，不失作劉備也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-031-143', 'p0127', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '吳書曰：璋以米二十萬斛，騎千匹，車千乘，繒絮錦帛，以資送劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-144', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '謙病篤，謂別駕麋笁曰：「非劉備不能安此州也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-145', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '獻帝春秋曰：陳登等遣使詣袁紹曰：「天降灾沴，禍臻鄙州，州將殂殞，生民無主，恐懼姦雄一旦承隙，以貽盟主日昃之憂，輒共奉故平原相劉備府君以為宗主，永使百姓知有依歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-146', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫盛曰：劉備雄才，處必亡之地，告急於吳，而獲奔助，無緣復顧望江渚而懷後計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-147', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏書載劉備與孫權語，與蜀志述諸葛亮與權語正同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-148', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉備未破魏軍之前，尚未與孫權相見，不得有此說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-149', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '傅子曰：初，劉備襲蜀，丞相掾趙戩曰：「劉備其不濟乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-150', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」徵士傅幹曰：「劉備寬仁有度，能得人死力。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-032-151', 'p0127', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '劉備代璋，以堅為廣漢、蜀郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-152', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」襄陽記曰：劉備訪世事於司馬德操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-153', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏略曰：劉備屯於樊城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-154', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '及荊州內附，孔明與劉備相隨去，福與韜俱來北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-155', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '其二事曰：曹公遣刺客見劉備，方得交接，開論伐魏形勢，甚合備計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-156', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '臣松之案：劉備以建安十三年敗，遣亮使吳，亮以建興五年抗表北伐，自傾覆至此整二十年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-157', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏略曰：始，國家以蜀中惟有劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-158', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '時左將軍劉備以亮有殊量，乃三顧亮於草廬之中；亮深謂備雄姿傑出，遂解帶寫誠，厚相結納。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-159', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-035-160', 'p0127', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '晚得諸葛亮，因以為佐相，而羣臣恱服，劉備足信、亮足重故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-036-161', 'p0127', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：曹公與劉備圍呂布於下邳，關羽啟公，布使秦宜祿行求救，乞娶其妻，公許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-036-162', 'p0127', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：初，劉備在許，與曹公共獵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-037-163', 'p0127', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '今劉備襲奪璋土，權以濟業，負信違情，德義俱愆，雖功由是隆，宜大傷其敗，譬斷手全軀，何樂之有？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-039-164', 'p0127', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '巴謂曹公曰：「劉備據荊州，不可也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-039-165', 'p0127', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '零陵先賢傳曰：璋遣法正迎劉備，巴諫曰：「備，雄人也，入必為害，不可內也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-045-166', 'p0127', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '僉父肜，復為劉備戰亡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-046-167', 'p0127', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '元惡旣斃，幼主東顧，俾保傅宣命，欲令諸軍振旅，然河北通謀黑山，曹操放毒東徐，劉表稱亂南荊，公孫瓚炰烋北幽，劉繇決力江滸，劉備爭盟淮隅，是以未獲承命櫜弓戢戈也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-168', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '劉備欲南濟江，肅與相見，因傳權旨，為陳成敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-169', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '劉備表權行車騎將軍，領徐州牧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-170', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二年四月，劉備稱帝於蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-171', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '魏略曰：權聞魏文帝受禪而劉備稱帝，乃呼問知星者，己分野中星氣何如，遂有僭意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-172', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」是歲，劉備帥軍來伐，至巫山、秭歸，使使誘導武陵蠻夷，假與印傳，許之封賞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-173', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '十二月，權使太中大夫鄭泉聘劉備于白帝，始復通也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-047-174', 'p0127', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」使蜀，劉備問曰：「吳王何以不荅吾書，得無以吾正名不宜乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-049-175', 'p0127', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '融欲告急平原相劉備，城中人無由得出，慈自請求行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-049-176', 'p0127', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '」備斂容荅曰：「孔北海知世間有劉備邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-050-177', 'p0127', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '術方與劉備爭徐州，以景為廣陵太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-051-178', 'p0127', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '年二十五，拜安東中郎將，與陸遜共拒劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-179', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後劉備表權行車騎將軍，昭為軍師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-180', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '建安二十年，權遣瑾使蜀通好劉備，與其弟亮俱公會相見，退無私面。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-181', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '劉備東伐吳，吳王求和，瑾與備牋曰：「奄聞旗鼓來至白帝，或恐議臣以吳王侵取此州，危害關羽，怨深禍大，不宜荅和，此用心於小，未留意於大者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-052-182', 'p0127', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '會劉備東下，武陵蠻夷蠢動，權遂命隲上益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-053-183', 'p0127', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '後劉備之東，宿於秣陵，周觀地形，亦勸權都之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-053-184', 'p0127', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '獻帝春秋云：劉備至京，謂孫權曰：「吳去此數百里，即有驚急，赴救為難，將軍無意屯京乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-053-185', 'p0127', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '諸書皆云劉備勸都秣陵，而此獨云權自欲都之，又為虛錯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-186', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-187', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備以左將軍領荊州牧，治公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-188', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備詣京見權，瑜上疏曰：「劉備以梟雄之姿，而有關羽、張飛熊虎之將，必非乆屈為人用者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-189', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備之自京還也，權乘飛雲大船，與張昭、秦松、魯肅等十餘人共追送之，大宴會敘別。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-190', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」瑜威聲遠著，故曹公、劉備咸欲疑譖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-191', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '加劉備天下梟雄，與操有隙，寄寓於表，表惡其能而不能用也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-192', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '臣松之案：劉備與權併力，共拒中國，皆肅之本謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-193', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權大怒，欲斬肅，肅因曰：「今事已急，即有他圖，何不遣兵助劉備，而欲斬我乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-194', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '今旣與曹操為敵，劉備近在公安，邊境密邇，百姓未附，宜得良將以鎮撫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-195', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '方今曹公在北，疆埸未靜，劉備寄寓，有似養虎，天下之事，未知終始，此朝士旰食之秋，至尊垂慮之日也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-196', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備負國，是非未決，羽亦何敢重欲干命！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-197', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉備令關羽鎮守，專有荊土，權命蒙西取長沙、零、桂三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-054-198', 'p0127', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '劉備請盟，權乃歸普等，割湘水，以零陵還之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-199', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權分荊州與劉備，普復還領江夏，遷盪寇將軍，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-200', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '子壹封宣城侯，領兵拒劉備有功，還赴南郡，與魏交戰，臨陣卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-201', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備次西陵，盛攻取諸屯，所向有功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-055-202', 'p0127', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '劉備出夷陵，璋與陸遜并力拒之，璋部下斬備護軍馮習等，所殺傷甚衆，拜平北將軍、襄陽太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-056-203', 'p0127', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '黃武元年，劉備舉兵攻宜都，然督五千人與陸遜并力拒備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-056-204', 'p0127', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '劉備詣京見權，範密請留備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-205', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '黃武元年，劉備率大衆來向西界，權命遜為大都督、假節，督朱然、潘璋、宋謙、韓當、徐盛、鮮于丹、孫桓等五萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-206', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '遜案劒曰：「劉備天下知名，曹操所憚，今在境界，此彊對也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-207', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '吳錄曰：劉備聞魏軍大出，書與遜云：「賊今已在江陵，吾將復東，將軍謂其能然不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-058-208', 'p0127', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '評曰：劉備天下稱雄，一世所憚，陸遜春秋方壯，威名未著，摧而克之，罔不如志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-060-209', 'p0127', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安二十四年，劉備將關羽圍樊、襄陽，琮上疏陳羽可討之計，權時已與呂蒙陰議襲之，恐事泄，故寢琮表不荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-061-210', 'p0127', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '劉備領荊州，以濬為治中從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-061-211', 'p0127', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '武陵郡從事樊伷誘導諸夷，圖以武陵屬劉備，外白差督督萬人往討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-062-212', 'p0127', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '劉備下白帝，權以見兵少，使綜料諸縣，得六千人，立解煩兩部，詳領左部、綜領右部督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-063-213', 'p0127', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '及壬辰歲，範又白言：「歲在甲午，劉備當得益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a04-063-214', 'p0127', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '」劉備盛兵西陵，範曰：「後當和親。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-001-215', 'p0127', 'jinshu', 'a05-001', '《晉書·卷一》', '從討張魯，言於魏武曰：「劉備以詐力虜劉璋，蜀人未附而遠爭江陵，此機不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-001-216', 'p0127', 'jinshu', 'a05-001', '《晉書·卷一》', '孫權、劉備，外親內踈，羽之得意，權所不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-001-217', 'p0127', 'jinshu', 'a05-001', '《晉書·卷一》', '帝恐達速發，以書喻之曰：「將軍昔棄劉備，託身國家，國家委將軍以疆埸之任，任將軍以圖蜀之事，可謂心貫白日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-014-218', 'p0127', 'jinshu', 'a05-014', '《晉書·卷十四》', '劉備章武元年，亦以郡國封建諸王，或遙採嘉名，不由檢土地所出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-014-219', 'p0127', 'jinshu', 'a05-014', '《晉書·卷十四》', '劉備據蜀，又分廣漢之葭萌、涪城、梓潼、白水四縣，改葭萌曰漢壽，又立漢德縣，以為梓潼郡；割巴郡之宕渠、宣漢、漢昌三縣置宕渠郡，尋省，以縣並屬巴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-014-220', 'p0127', 'jinshu', 'a05-014', '《晉書·卷十四》', '二十一年，劉備分巴郡立固陵郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0127-a05-015-221', 'p0127', 'jinshu', 'a05-015', '《晉書·卷十五》', '蜀分南郡，立宜都郡，劉備沒後，宜都、武陵、零陵、南郡四郡之地悉復屬吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-0', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '劉禪以為左將軍，脩欲刺禪而不得親近，每因慶賀，且拜且前，為禪左右所遏，事輙不克，故殺禕焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-1', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '魏之與蜀，雖為敵國，非有趙襄滅智之仇，燕丹危亡之急；且劉禪凡下之主，費禕中才之相，二人存亡，固無關於興喪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-2', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是月，蜀主劉禪詣艾降，巴蜀皆平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-004-3', 'p0128', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」丁亥，封劉禪為安樂公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-009-4', 'p0128', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '飛知其良家女，遂以為妻，產息女，為劉禪皇后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-5', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '劉禪遣使奉皇帝璽綬，為箋詣艾請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-6', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '方鄧艾以萬人入江由之危險，鍾會以二十萬衆留劒閣而不得進，三軍之士已飢，艾雖戰勝克將，使劉禪數日不降，則二將之軍難以反矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-7', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '今宜厚劉禪以致孫休，安士民以來遠人，若便送禪於京都，吴以為流徙，則於向化之心不勸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-8', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾受命忘身，束馬縣車，自投死地，勇氣陵雲，士衆乘勢，使劉禪君臣靣縛，叉手屈膝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-028-9', 'p0128', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾進軍向成都，劉禪詣艾降，遣使勑維等令降於會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-033-10', 'p0128', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '晉諸公贊曰：劉禪乘騾車詣艾，不具亡國之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-033-11', 'p0128', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '皇帝臨軒，使太常嘉命劉禪為安樂縣公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-035-12', 'p0128', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '幸值劉禪闇弱，無猜險之性，諸葛威略，足以檢衞異端，故使異同之心無由自起耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-042-13', 'p0128', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '張璠以為譙周所陳降魏之策，蓋素料劉禪懦弱，心無害戾，故得行也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-044-14', 'p0128', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」　孫盛晉陽秋曰：盛以永和初從安西將軍平蜀，見諸故老，及姜維旣降之後密與劉禪表疏，說欲偽服事鍾會，因殺之以復蜀土，會事不捷，遂至泯滅，蜀人于今傷之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a04-048-15', 'p0128', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '蜀主劉禪降魏問至，然後罷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-002-16', 'p0128', 'jinshu', 'a05-002', '《晉書·卷二》', '以劉禪之闇，而邊城外破，士女內震，其亡可知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-003-17', 'p0128', 'jinshu', 'a05-003', '《晉書·卷三》', '賜山陽公劉康、安樂公劉禪子弟一人為駙馬都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-005-18', 'p0128', 'jinshu', 'a05-005', '《晉書·卷五》', '然後推轂鍾鄧，長驅庸蜀，三關電埽，劉禪入臣，天符人事，於是信矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-014-19', 'p0128', 'jinshu', 'a05-014', '《晉書·卷十四》', '劉禪建興二年，改益州郡為建寧郡，廣漢屬國為陰平郡，分建寧永昌立雲南郡，分建寧䍧牱立興古郡，分廣漢立東廣漢郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-034-20', 'p0128', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '至劉禪降服，諸營堡者索然俱散。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0128-a05-034-21', 'p0128', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '今江淮之難，不過劍閣；山川之險，不過岷漢；孫皓之暴，侈於劉禪；吳人之困，甚於巴蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a03-086-0', 'p0129', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '故諸葛亮表云「五月度瀘」，言其艱苦也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a03-113-1', 'p0129', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '諸葛亮表有耽文山、澤山、司彌瘞山、婁山、辟龍山，此等並皆未詳所在縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a03-113-2', 'p0129', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」諸葛亮書云：「漢嘉金，朱提銀，採之不足以自食。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-3', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '諸葛亮聞之，陰欲誘達，數書招之，達與相報荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-4', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '蜀大將諸葛亮寇邊，天水、南安、安定三郡吏民叛應亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-5', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '諸葛亮棄父母之國，阿殘賊之黨，神人被毒，惡積身滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-6', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '十二月，諸葛亮圍陳倉，曹真遣將軍費曜等拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-7', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '諸葛亮寇天水，詔大將軍司馬宣王拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-8', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '是月，諸葛亮出斜谷，屯渭南，司馬宣王率諸軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-003-9', 'p0129', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '羣臣以為大將軍方與諸葛亮相持未解，車駕可西幸長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-006-10', 'p0129', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '文帝時為侍中，太和中卒，巽在荊州，目龐統為半英雄，證裴潛終以清行顯；統遂附劉備，見待次於諸葛亮，潛位至尚書令，並有名德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-009-11', 'p0129', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '諸葛亮圍祁山，南安、天水、安定三郡反應亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-010-12', 'p0129', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '吳、蜀雖蕞爾小國，依岨山水，劉備有雄才，諸葛亮善治國，孫權識虛實，陸議見兵勢，據險守要，汎舟江湖，皆難卒謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-013-13', 'p0129', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '太和初，蜀相諸葛亮圍祁山，明帝欲西征，毓上疏曰：「夫策貴廟勝，功尚帷幄，不下殿堂之上，而決勝千里之外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-14', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '若小緩之，諸葛亮明於治而為相，關羽、張飛勇冠三軍而為將，蜀民旣定，據險守要，則不可犯矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-15', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資別傳曰：諸葛亮出在南鄭，時議者以為可因大發兵，就討之，帝意亦然，以問資。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-16', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '青龍初，孫權與諸葛亮連和，欲俱出為寇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-014-17', 'p0129', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '資別傳曰：是時，孫權、諸葛亮號稱劇賊，無歲不有軍征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-18', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '太和中，諸葛亮出隴右，吏民騷動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-19', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '後十餘日，諸軍上隴，諸葛亮破走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-20', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '會諸葛亮出，緝上便宜，詔以問中書令孫資，資以為有籌略，遂召拜騎都尉，遣參征蜀軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-015-21', 'p0129', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '魏略曰：建字公威，少與諸葛亮俱遊學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-017-22', 'p0129', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '諸葛亮復出，急攻陳倉，帝驛馬召郃到京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-017-23', 'p0129', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '郃識變數，善處營陣，料戰勢地形，無不如計，自諸葛亮皆憚之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-017-24', 'p0129', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '諸葛亮復出祁山，詔郃督諸將西至略陽，亮還保祁山，郃追至木門，與亮軍交戰，飛矢中郃右膝，薨，魏略曰：亮軍退，司馬宣王使郃追之，郃曰：「軍法，圍城必開出路，歸軍勿追。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-022-25', 'p0129', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '大將軍司馬文王曰：「昔諸葛亮常有此志，卒亦不能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-022-26', 'p0129', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」諸葛亮寇天水，臻奏：「宜遣奇兵入散關，絕其糧道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-023-27', 'p0129', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '諸葛亮出秦川，大將軍曹真督諸軍拒亮，徙襲為大將軍軍師，分邑百戶賜兄基爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-023-28', 'p0129', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '魏略列傳以徐福、嚴幹、李義、張旣、游楚、梁習、趙儼、裴潛、韓宣、黃朗十人共卷，其旣、習、儼、潛四人自有傳，徐福事在諸葛亮傳，游楚事在張旣傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-025-29', 'p0129', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '帝方脩殿舍，百姓勞役，毗上疏曰：「竊聞諸葛亮講武治兵，而孫權巿馬遼東，量其意指，似欲相左右。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-025-30', 'p0129', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '魏略曰：諸葛亮圍祁山，不克，引退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-025-31', 'p0129', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '青龍二年，諸葛亮率衆出渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-026-32', 'p0129', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '招以蜀虜諸葛亮數出，而比能狡猾，能相交通，表為防備，議者以為縣遠，未之信也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-026-33', 'p0129', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '太和二年，蜀相諸葛亮出祁山，遣將軍馬謖至街亭，高詳屯列柳城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-026-34', 'p0129', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '青龍二年，諸葛亮出斜谷，並田于蘭坑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-027-35', 'p0129', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '至，值諸葛亮出祁山，隴右三郡反，邈輙遣參軍及金城太守等擊南安賊，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-028-36', 'p0129', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」袁子曰：諸葛亮，重人也，而驟用蜀兵，此知小國弱民難以乆存也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-028-37', 'p0129', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會徑過，西出陽安口，遣人祭諸葛亮之墓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-029-38', 'p0129', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '先生見諸葛亮連弩，曰：『巧則巧矣，未盡善也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-031-39', 'p0129', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '後丞相諸葛亮問秦宓以扶所長，宓曰：「董扶襃秋毫之善，貶纖芥之惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-031-40', 'p0129', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '丞相諸葛亮平南土，闡還吳，為御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-41', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '過襄陽，諸葛亮說先主攻琮，荊州可有。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-42', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主棄妻子，與諸葛亮、張飛、趙雲等數十騎走，曹公大獲其人衆輜重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-43', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主遣諸葛亮自結於孫權，江表傳曰：孫權遣魯肅弔劉表二子，并令與備相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-44', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備大喜，進住鄂縣，即遣諸葛亮隨肅詣孫權，結同盟誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-45', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮詣吳未還，備聞曹公軍下，恐懼，日遣邏吏於水次候望權軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-46', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '臣松之案：魏書載劉備與孫權語，與蜀志述諸葛亮與權語正同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-47', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」使關羽屯江陵，張飛屯秭歸，諸葛亮據南郡，備自住潺陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-48', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主留諸葛亮、關羽等據荊州，將步卒數萬人入益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-49', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-50', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮達治知變，正而有謀，而為之相；張飛、關羽勇而有義，皆萬人之敵，而為之將：此三人者，皆人傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-51', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-52', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '援亦少有名行，太尉皇甫嵩賢其才而以女妻之，丞相諸葛亮以援為祭酒，遷從事中郎，卒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-53', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-54', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '太傅許靖、安漢將軍糜笁、軍師將軍諸葛亮、太常賴恭、光祿勳黃柱、少府王謀等上言：「曹丕篡弒，湮滅漢室，竊據神器，劫迫忠良，酷烈無道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-55', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '以諸葛亮為丞相，許靖為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-56', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮集載先主遺詔勑後主曰：「朕初疾但下痢耳，後轉雜他病，殆不自濟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-032-57', 'p0129', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '及其舉國託孤於諸葛亮，而心神無貳，誠君臣之至公，古今之盛軌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-58', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '初備以諸葛亮為太子太傅，及禪立，以亮為丞相，委以諸事，謂亮曰：「政由葛氏，祭則寡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-59', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '又諸葛亮以禪立之明年領益州牧，其年與主簿杜微書曰「朝廷今年十八」，與禪傳相應，理當非虛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-60', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '又案諸書記及諸葛亮集，亮亦不為太子太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-61', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '諸葛亮誅房諸子，徙其四弟於越嶲，欲以安之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-62', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '諸葛亮集載禪三月下詔曰：「朕聞天地之道，福仁而禍淫；善積者昌，惡積者喪，古今常數也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-63', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '雖使諸葛亮在，不能輔之乆全，而況姜維邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-033-64', 'p0129', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '諸葛亮雖達於為政，凡此之類，猶有未周焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-034-65', 'p0129', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '夫人欲將太子歸吳，諸葛亮使趙雲勒兵斷江留太子，乃得止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-66', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '諸葛亮字孔明，琅邪陽都人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-67', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」　臣松之以為魏略此言，謂諸葛亮為公威計者可也，若謂兼為己言，可謂未達其心矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-68', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '初平中，中州兵起，乃與韜南客荊州，到，又與諸葛亮特相善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-69', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '逮大和中，諸葛亮出隴右，聞元直、廣元仕財如此，嘆曰：「魏殊多士邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-70', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '蜀記曰：晉初，扶風王駿鎮關中，司馬高平劉寶、長史熒陽桓隰諸官屬士大夫共論諸葛亮，于時譚者多譏亮託身非所，勞困蜀民，力小謀大，不能度德量力。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-71', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '臣壽等言：臣前在著作郎，侍中領中書監濟北侯臣荀勗、中書令關內侯臣和嶠奏，使臣定故蜀丞相諸葛亮故事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-72', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '晉泰始起居注載詔曰：「諸葛亮在蜀，盡其心力，其子瞻臨難而死義，天下之善一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-73', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '漢晉春秋曰：樊建為給事中，晉武帝問諸葛亮之治國，建對曰：「聞惡必改，而不矜過，賞罰之信，足感神明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-74', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '評曰：諸葛亮之為相國也，撫百姓，示儀軌，約官職，從權制，開誠心，布公道；盡忠益時者雖讎必賞，犯法怠慢者雖親必罰，服罪輸情者雖重必釋，游辭巧飾者雖輕必戮；善無微而不賞，惡無纖而不貶；庶事精練，物理其本，循名責實，虛偽不齒；終於邦域之內，咸畏而愛之，刑政雖峻而無怨者，以其用心平而勸戒明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-75', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-76', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '晚得諸葛亮，因以為佐相，而羣臣恱服，劉備足信、亮足重故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-77', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '亮死至今數十年，國人歌思，如周人之思召公也，孔子曰「雍也可使南靣」，諸葛亮有焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-78', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '又問諸葛亮始出隴右，南安、天水、安定三郡人反應之，若亮速進，則三郡非中國之有也，而亮徐行不進；旣而官兵上隴，三郡復，亮無尺寸之功，失此機，何也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-035-79', 'p0129', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '曰：子之論諸葛亮，則有證也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-80', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '羽聞馬超來降，舊非故人，羽書與諸葛亮，問超人才可誰比類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-81', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '興字安國，少有令問，丞相諸葛亮深器異之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-82', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主入益州，還攻劉璋，飛與諸葛亮等泝流而上，分定郡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-83', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '益州旣平，賜諸葛亮、法正、飛及關羽金各五百斤，銀千斤，錢五千萬，錦千匹，其餘頒賜各有差，以飛領巴西太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-84', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '故羽聞馬超歸降，以書問諸葛亮「超人才可誰比類」，不得如書所云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-85', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '是歲，先主為漢中王，欲用忠為後將軍，諸葛亮說先主曰：「忠之名望，素非關、馬之倫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-86', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主自葭萌還攻劉璋，召諸葛亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-87', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '五年，隨諸葛亮駐漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-036-88', 'p0129', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-89', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」諸葛亮亦言之於先主，先主見與善譚，大器之，以為治中從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-90', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '」親待亞於諸葛亮，遂與亮並為軍師中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-91', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '拜統父議郎，遷諫議大夫，諸葛亮親為之拜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-92', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '或謂諸葛亮曰：「法正於蜀郡太縱橫，將軍宜啟主公，抑其威福。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-037-93', 'p0129', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '諸葛亮與正，雖好尚不同，以公義相取。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-038-94', 'p0129', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '優游風儀，性簡傲跌宕，在先主坐席，猶箕踞傾倚，威儀不肅，自縱適；諸葛亮已下則獨擅一榻，項枕卧語，無所為屈。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-038-95', 'p0129', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '後遷昭文將軍，與諸葛亮、法正、劉巴、李嚴共造蜀科；蜀科之制，由此五人焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-96', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '先主定蜀，徵和為掌軍中郎將，與軍師將軍諸葛亮並署左將軍大司馬府事，獻可替否，共為歡交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-97', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '時諸葛亮在臨烝，巴與亮書曰：「乘危歷險，到值思義之民，自與之衆，承天之心，順物之性，非余身謀所能勸動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-98', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '諸葛亮謂巴曰：「張飛雖實武人，敬慕足下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-99', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '卒後，魏尚書僕射陳羣與丞相諸葛亮書，問巴消息，稱曰劉君子初，甚敬重焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-100', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '及先主入蜀，諸葛亮亦從往，良留荊州，與亮書曰：「聞雒城已拔，此天祚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-101', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '才器過人，好論軍計，丞相諸葛亮深加器異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-102', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '」　習鑿齒曰：諸葛亮之不能兼上國也，豈不宜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-103', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '七年，孫權稱尊號，以震為衞尉，賀權踐阼，諸葛亮與兄瑾書曰：「孝起忠純之性，老而益篤，及其贊述東西，歡樂和合，有可貴者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-104', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '九年，都護李平坐誣罔廢；諸葛亮與長史蔣琬、侍中董允書曰：「孝起前臨至吳，為吾說正方腹中有鱗甲，鄉黨以為不可近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-105', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '雖甞有鳴吠之益於時務，然旣已任之，勢不得輕，若一朝無諸葛亮，必為禍亂矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-106', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '諸葛亮聞之，以為知言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-107', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '華陽國志曰：時蜀人以諸葛亮、蔣琬、費禕及允為四相，一號四英也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-039-108', 'p0129', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '丞相諸葛亮連年出軍，調發諸郡，多不相救，乂募取兵五千人詣亮，慰喻檢制，無逃竄者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-109', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '及先主入蜀，自葭萌還攻劉璋，時封年二十餘，有武藝，氣力過人，將兵俱與諸葛亮、張飛等泝流西上，所在戰克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-110', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮慮封剛猛，易世之後終難制御，勸先主因此除之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-111', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮雖外接待羕，而內不能善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-112', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '羕於獄中與諸葛亮書曰：「僕昔有事於諸侯，以為曹操暴虐，孫權無道，振威闇弱，其惟主公有霸王之器，可與興業致治，故乃翻然有輕舉之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-113', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '先主入蜀，諸葛亮鎮荊土，孫權遣使通好於亮，因問士人皆誰相經緯者，亮荅曰：「龐統、廖立，楚之良才，當贊興世業者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-114', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '立本意，自謂才名宜為諸葛亮之貳，而更游散在李嚴等下，常懷怏怏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-115', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '」邵、琬具白其言於諸葛亮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-116', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '立躬率妻子耕殖自守，聞諸葛亮卒，垂泣歎曰：「吾終為左袵矣！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-117', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '三年，先主疾病，嚴與諸葛亮並受遺詔輔少主；以嚴為中都護，統內外軍事，留鎮永安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-118', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '以諸葛亮欲出軍漢中，嚴當知後事，移屯江州，留護軍陳到駐永安，皆統屬嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-119', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮集有嚴與亮書，勸亮宜受九錫，進爵稱王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-120', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮又與平子豐教曰：「吾與君父子戮力以獎漢室，此神明所聞，非但人知之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-121', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮之使廖立垂泣，李平致死，豈徒無怨言而已哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-122', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '諸葛亮於是可謂能用刑矣，自秦、漢已來未之有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-123', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '五年，諸葛亮駐漢中，更以延為督前部，領丞相司馬、涼州刺史，八年，使延西入羌中，魏後將軍費瑤、雍州刺史郭淮與延戰于陽谿，延大破淮等，遷為前軍師征西大將軍，假節，進封南鄭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-040-124', 'p0129', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '魏略曰：諸葛亮病，謂延等云：「我之死後，但謹自守，慎勿復來也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-125', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主甚悼惜，乃詔諸葛亮曰：「峻旣佳士，加有功於國，欲行酹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-126', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '丞相諸葛亮北駐漢中，請為記室，使與子喬共周旋游處。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-127', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '時南方諸郡不賔，諸葛亮將自征之，連諫以為「此不毛之地，疫癘之鄉，不宜以一國之望，冒險而行」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-128', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '諸葛亮當北行，表與後主曰：「將軍向寵，性行淑均，曉暢軍事，試用於昔，先帝稱之曰能，是以衆論舉寵為督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-129', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '會先主薨，諸葛亮遣鄧芝使吳，亮令芝言次可從權請裔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-130', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主爭漢中，急書發兵，軍師將軍諸葛亮以問洪，洪曰：「漢中則益州咽喉，存亡之機會，若無漢中則無蜀矣，此家門之禍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-131', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '漢嘉太守黃元素為諸葛亮所不善，聞先主疾病，懼有後患，舉郡反，燒臨邛城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-132', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '是以西土咸服諸葛亮能盡時人之器用也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-133', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '時諸葛亮用法峻密，陰聞祗游戲放縱，不勤所職，常奄往錄獄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-134', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '建興三年，隨諸葛亮南行，歸至漢陽縣，降人李鴻來詣亮，亮見鴻，時蔣琬與詩在坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-041-135', 'p0129', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '達曰：『諸葛亮見顧有本末，終不爾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-042-136', 'p0129', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '諸葛亮表請其罪，先主荅曰：「芳蘭生門，不得不鉏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-042-137', 'p0129', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '立上言：「故蜀大官及盡忠死事者子孫，雖仕郡國，或有不才，同之齊民為劇；又諸葛亮、蔣琬、費禕等子孫流徙中畿，各宜量才叙用，以慰巴、蜀之心，傾吳人之望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-043-138', 'p0129', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '」宣王與諸葛亮書曰：「黃公衡，快士也，每坐起歎述足下，不去口實。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-139', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '軍師將軍諸葛亮請曰：「蔣琬，社稷之器，非百里之才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-140', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '琬以為昔諸葛亮數闚秦川，道險運艱，竟不能克，不若乘水東下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-141', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及至喪所，諸葛亮及諸貴人悉集，車乘甚鮮，允猶神色未泰，而禕晏然自若。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-044-142', 'p0129', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '建興六年，丞相諸葛亮軍向祁山，時天水太守適出案行，維及功曹梁緒、主簿尹賞、主記梁虔等從行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-143', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '丞相諸葛亮深慮權聞先主殂隕，恐有異計，未知所如。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-144', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」芝對曰：「吳、蜀二國四州之地，大王命世之英，諸葛亮亦一時之傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-145', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '恭子厷，為丞相西曹令史，隨諸葛亮於漢中，早夭，亮甚惜之，與留府長史參軍張裔、蔣琬書曰：「令史失賴厷，掾屬喪楊顒，為朝中損益多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-146', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '入蜀，為巴郡太守，丞相諸葛亮主簿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-147', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '」有司將殺之，諸葛亮為請，得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-045-148', 'p0129', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '益部耆舊雜記曰：諸葛亮於武功病篤，後主遣福省侍，遂因諮以國家大計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-047-149', 'p0129', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '備進住夏口，使諸葛亮詣權，權遣周瑜、程普等行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-047-150', 'p0129', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '是時蜀相諸葛亮出武功，權謂魏明帝不能遠出，而帝遣兵助司馬宣王拒亮，自率水軍東征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-051-151', 'p0129', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '蜀丞相諸葛亮與兄瑾書曰：「旣受東朝厚遇，依依於子弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-052-152', 'p0129', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後與張溫俱使蜀，諸葛亮甚稱歎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-053-153', 'p0129', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '權為吳王，及稱尊號，畯嘗為衞尉，使至蜀，蜀相諸葛亮深善之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-054-154', 'p0129', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時劉備為曹公所破，欲引南渡江，與魯肅遇於當陽，遂共圖計，因進住夏口，遣諸葛亮詣權，權遂遣瑜及程普等與備并力逆曹公，遇於赤壁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-054-155', 'p0129', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '時諸葛亮與備相隨，肅謂亮曰「我子瑜友也」，即共定交。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-054-156', 'p0129', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '又語諸葛亮曰「我子瑜友也」，則亮已亟聞肅言矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-057-157', 'p0129', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '然諸葛亮達見計數，必知神慮屈申之宜，加受朝廷天覆之惠，推亮之心，必無疑貳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-057-158', 'p0129', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」諸葛亮聞俊憂溫，意未之信，及溫放黜，亮乃歎俊之有先見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-058-159', 'p0129', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '備尋病亡，子禪襲位，諸葛亮秉政，與權連和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-060-160', 'p0129', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '東主中營自掩石陽，別遣從弟孫奐治安陸城，脩立邸閣，輦貲運糧，以為軍儲，又命諸葛亮進指關西，江邊諸將無復在者，才留三千所兵守武昌耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-062-161', 'p0129', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '蜀相諸葛亮卒，權垂心西州，遣儀使蜀申固盟好。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a04-064-162', 'p0129', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '諸葛亮聞恪代詳，書與陸遜曰：「家兄年老，而恪性踈，今使典主糧穀，糧穀軍之要最，僕雖在遠，竊用不安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-001-163', 'p0129', 'jinshu', 'a05-001', '《晉書·卷一》', '蜀相諸葛亮惡其反覆，又慮其為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-001-164', 'p0129', 'jinshu', 'a05-001', '《晉書·卷一》', '諸葛亮欲相破，惟苦無路耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-001-165', 'p0129', 'jinshu', 'a05-001', '《晉書·卷一》', '明年，諸葛亮寇天水，圍將軍賈嗣、魏平於祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-003-166', 'p0129', 'jinshu', 'a05-003', '《晉書·卷三》', '」己未，詔蜀相諸葛亮孫京隨才署吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-009-167', 'p0129', 'jinshu', 'a05-009', '《晉書·卷九》', '遺詔以桓溫輔政，依諸葛亮、王導故事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-011-168', 'p0129', 'jinshu', 'a05-011', '《晉書·卷十一》', '陳卓、范蠡、鬼谷先生、張良、諸葛亮、譙周、京房、張衡並云：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-012-169', 'p0129', 'jinshu', 'a05-012', '《晉書·卷十二》', '」五年三月，諸葛亮以大衆寇天水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-012-170', 'p0129', 'jinshu', 'a05-012', '《晉書·卷十二》', '」是年四月，諸葛亮據渭南，吳亦起兵應之，魏東西奔命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-171', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '」其七月，車騎將軍張郃追諸葛亮，為亮所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-172', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '是時，諸葛亮據渭南，宣帝與相持；孫權寇合肥，又遣陸議、孫昭等入淮沔，天子親東征。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-173', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '又明年，諸葛亮入秦川。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-013-174', 'p0129', 'jinshu', 'a05-013', '《晉書·卷十三》', '蜀後主建興十三年，諸葛亮帥大衆伐魏，屯於渭南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0129-a05-037-175', 'p0129', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '每諸葛亮入寇關中，邊兵不能制敵，中軍奔赴，輒不及事機，宜預選步騎二萬，以爲二部，爲討賊之備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-028-0', 'p0130', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '蜀衞將軍諸葛瞻自涪還綿竹，列陳待艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-028-1', 'p0130', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾遂至緜竹，大戰，斬諸葛瞻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-033-2', 'p0130', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬，鄧艾破衞將軍諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-036-3', 'p0130', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '苞子遵為尚書，隨諸葛瞻於緜竹，與鄧艾戰，死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-043-4', 'p0130', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '權留蜀子崇，為尚書郎，隨衞將軍諸葛瞻拒鄧艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-043-5', 'p0130', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '恢弟子球，羽林右部督，隨諸葛瞻拒鄧艾，臨陣授命，死于緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-043-6', 'p0130', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '侍中諸葛瞻，丞相亮之子，恪從弟也，嶷與書曰：「東主初崩，帝實幼弱，太傅受寄託之重，寄託之重，亦何容易！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-044-7', 'p0130', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '而鄧艾自陰平由景谷道傍入，遂破諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-044-8', 'p0130', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '但鄧艾詭道傍入，出於其後，諸葛瞻旣敗，成都自潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a04-045-9', 'p0130', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '時都護諸葛瞻初統朝事，廖化過預，欲與預共詣瞻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0130-a05-002-10', 'p0130', 'jinshu', 'a05-002', '《晉書·卷二》', '十一月，鄧艾帥萬餘人自陰平踰絕險至江由，破蜀將諸葛瞻於緜竹，斬瞻，傳首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a03-074-0', 'p0131', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '蜀志曰：「曹公使張遼及關羽為先鋒，羽望見良麾蓋，策馬刺良萬衆之中，斬其首還，諸將莫能當，遂解白馬圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a03-075-1', 'p0131', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫權破關羽，取荊州，以璋為益州牧，留住秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-2', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '備將關羽屯下邳，復進攻之，羽降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-3', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '使張遼、關羽前登，擊破，斬良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-4', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '時關羽彊盛，而王在鄴，留必典兵督許中事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-5', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，曹仁討關羽，屯樊城，是月使仁圍宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-6', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '曹瞞傳曰：是時南陽間苦繇役，音於是執太守東里襃，與吏民共反，與關羽連和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-7', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '吾與子共戮力，比曹公軍來，關羽兵亦至矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-001-8', 'p0131', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '孫權遣使上書，以討關羽自效。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-003-9', 'p0131', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '布之被圍，關羽屢請於太祖，求以杜氏為妻，太祖疑其有色，及城陷，太祖見之，乃自納之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-009-10', 'p0131', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '關羽攻樊，時漢水暴溢，于禁等七軍皆沒，禁降羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-013-11', 'p0131', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '魏略曰：孫權稱臣，斬送關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-013-12', 'p0131', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '」肅曰：「昔關羽率荊州之衆，降于禁於漢濵，遂有北向爭天下之志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-013-13', 'p0131', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '今淮南將士父母妻子皆在內州，但急往禦衞，使不得前，必有關羽土崩之勢矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-14', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備有英名，關羽、張飛皆萬人敵也，權必資之以禦我。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-15', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張飛、關羽者，皆萬人之敵也，為之死用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-16', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖令劉備拒袁術，昭曰：「備勇而志大，關羽、張飛為之羽翼，恐備之心未可得論也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-17', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '及關羽圍曹仁於樊，孫權遣使辭以「遣兵西上，欲掩取羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-18', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '若小緩之，諸葛亮明於治而為相，關羽、張飛勇冠三軍而為將，蜀民旣定，據險守要，則不可犯矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-19', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '詔問羣臣令料劉備當為關羽出報吳不。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-20', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '且關羽與備，義為君臣，恩猶父子；羽死不能為興軍報敵，於終始之分不足。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-21', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '權前襲殺關羽，取荊州四郡，備怒，必大興師伐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-014-22', 'p0131', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '劉備、孫權，外親內踈，關羽得志，權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-015-23', 'p0131', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '關羽驍銳，乘利而進，必將為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-24', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '關羽圍曹仁於樊，會權稱藩，召遼及諸軍悉還救仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-25', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '遼未至，徐晃已破關羽，仁圍解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-26', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '後從平荊州，留屯襄陽，擊關羽、蘇非等，皆走之，南郡諸縣山谷蠻夷詣進降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-27', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '建安二十四年，太祖在長安，使曹仁討關羽於樊，又遣禁助仁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-28', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '帝使豫於陵屋畫關羽戰克、龐悳憤怒、禁降服之狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-29', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '又與滿寵討關羽於漢津，與曹仁擊周瑜於江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-017-30', 'p0131', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復遣晃助曹仁討關羽，屯宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-018-31', 'p0131', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '劉備與周瑜圍曹仁於江陵，別遣關羽絕北道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-018-32', 'p0131', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '與樂進討關羽於尋口，有功，進封延壽亭侯，加討逆將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-018-33', 'p0131', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '侯音、衞開等以宛叛，悳將所領與曹仁共攻拔宛，斬音、開，遂南屯樊，討關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-019-34', 'p0131', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '二十四年，曹仁為關羽所圍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-021-35', 'p0131', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孫權自破關羽并荊州之後，志盈欲滿，凶宄以極，是以宣文侯深建宏圖大舉之策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-022-36', 'p0131', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '曹仁為關羽所圍，太祖遣徐晃救之，不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-023-37', 'p0131', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '關羽圍征南將軍曹仁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-026-38', 'p0131', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '關羽圍襄陽，寵助征南將軍曹仁屯樊城拒之，而左將軍于禁等軍以霖雨水長為羽所沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-031-39', 'p0131', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '孫權殺關羽，取荊州，以璋為益州牧，駐秭歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-40', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '靈等還，先主乃殺徐州刺史車胄，留關羽守下邳，而身還小沛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-41', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '旣去，備謂張飛、關羽曰：「吾豈種菜者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-42', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曹公盡收其衆，虜先主妻子，并禽關羽以歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-43', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '比到當陽，衆十餘萬，輜重數千兩，日行十餘里，別遣關羽乘船數百艘，使會江陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-44', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」備謂關羽、張飛曰：「彼欲致我，我今自結託於東而不往，非同盟之意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-45', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」使關羽屯江陵，張飛屯秭歸，諸葛亮據南郡，備自住潺陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-46', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主留諸葛亮、關羽等據荊州，將步卒數萬人入益州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-47', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '孫氏與孤本為脣齒，又樂進在青泥與關羽相拒，今不往救羽，進必大克，轉侵州界，其憂有甚於魯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-48', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主軍益彊，分遣諸將平下屬縣，諸葛亮、張飛、趙雲等將兵泝流定白帝、江州、江陽，惟關羽留鎮荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-49', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '諸葛亮達治知變，正而有謀，而為之相；張飛、關羽勇而有義，皆萬人之敵，而為之將：此三人者，皆人傑也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-50', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主復領益州牧，諸葛亮為股肱，法正為謀主，關羽、張飛、馬超為爪牙，許靖、麋笁、簡雍為賔友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-51', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主引兵五萬下公安，令關羽入益陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-52', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '軍師將軍臣諸葛亮、盪寇將軍漢壽亭侯臣關羽、征虜將軍新亭侯臣張飛、征西將軍臣黃忠、鎮遠將軍臣賴恭、揚武將軍臣法正、興業將軍臣李嚴等一百二十人上言曰：昔唐堯至聖而四凶在朝，周成仁賢而四國作難，高后稱制而諸呂竊命，孝昭幼冲而上官逆謀，皆馮世寵，藉履國權，窮凶極亂，社稷幾危。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-53', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '時關羽攻曹公將曹仁，禽于禁於樊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-54', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '又前關羽圍樊、襄陽，襄陽男子張嘉、王休獻玉璽，璽潛漢水，伏於淵泉，暉景燭燿，靈光徹天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-032-55', 'p0131', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '初，先主忿孫權之襲關羽，將東征，秋七月，遂帥諸軍伐吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-033-56', 'p0131', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '三年秋九月，追謚故將軍關羽、張飛、馬超、龐統、黃忠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-57', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '關羽、張飛等不恱，先主解之曰：「孤之有孔明，猶魚之有水也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-58', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」亮曰：「豫州軍雖敗於長阪，今戰士還者及關羽水軍精甲萬人，劉琦合江夏戰士亦不下萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-59', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '關羽為曹公所獲，遇之甚厚，可謂能盡其用矣，猶義不背本，曾謂孔明之不若雲長乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-60', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '然後吳更違盟，關羽毀敗，秭歸蹉跌，曹丕稱帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-035-61', 'p0131', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '袁子曰：或問諸葛亮何如人也，袁子曰：張飛、關羽與劉備俱起，爪牙腹心之臣，而武人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-62', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '關羽字雲長，本字長生，河東解人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-63', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：曹公與劉備圍呂布於下邳，關羽啟公，布使秦宜祿行求救，乞娶其妻，公許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-64', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '曹公議徙許都以避其銳，司馬宣王、蔣濟以為關羽得志，孫權必不願也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-65', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '張飛字益德，涿郡人也，少與關羽俱事先主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-66', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '益州旣平，賜諸葛亮、法正、飛及關羽金各五百斤，銀千斤，錢五千萬，錦千匹，其餘頒賜各有差，以飛領巴西太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-67', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，飛雄壯威猛，亞於關羽，魏謀臣程昱等咸稱羽、飛萬人之敵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-68', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '山陽公載記曰：超因見備待之厚，與備言，常呼備字，關羽怒，請殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-69', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '為呼人主字，幾為關羽、張飛所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-70', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '且備之入蜀，留關羽鎮荊州，羽未甞在益土也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-71', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '初，先主時，惟法正見謚；後主時，諸葛亮功德蓋世，蔣琬、費禕荷國之重，亦見謚；陳祗寵待，特加殊獎，夏侯霸遠來歸國，故復得謚；於是關羽、張飛、馬超、龐統、黃忠及雲乃追謚，時論以為榮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-036-72', 'p0131', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '評曰：關羽、張飛皆稱萬人之敵，為世虎臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-037-73', 'p0131', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '先主旣即尊號，將東征孫權以復關羽之耻，羣臣多諫，一不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-038-74', 'p0131', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '芳為南郡太守，與關羽共事，而私好攜貳，叛迎孫權，羽因覆敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-040-75', 'p0131', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '自關羽圍樊城、襄陽，連呼封、達，令發兵自助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-040-76', 'p0131', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '建安中，為荊州刺史傅羣主簿，背羣而詣襄陽太守關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-041-77', 'p0131', 'sanguozhi', 'a04-041', '《三國志·蜀書十一》', '先主為漢中王，遣詩拜關羽為前將軍，羽聞黃忠為後將軍，羽怒曰：「大丈夫終不與老兵同列！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-045-78', 'p0131', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '為前將軍關羽主簿，羽敗，屬吳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-045-79', 'p0131', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '士仁字君義，廣陽人也，為將軍，住公安，統屬關羽；與羽有隙，叛迎孫權。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-045-80', 'p0131', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '先主入蜀，以為荊州治中，典留州事，亦與關羽不穆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-81', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」遂置南三郡長吏，關羽盡逐之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-82', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '會備到公安，使關羽將三萬兵至益陽，權乃召蒙等使還助肅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-83', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '二十四年，關羽圍曹仁於襄陽，曹公遣左將軍于禁救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-84', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '關羽還當陽，西保麥城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-85', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '復與關羽更相覘伺，逐利見便，挾為卑辭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-86', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '後領護于禁軍，軍沒，為關羽所得。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-87', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '及文帝即王位，權乃遣周，為牋魏王曰：「昔討關羽，獲于將軍，即白先王，當發遣之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-047-88', 'p0131', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '雖致命虜庭，梟獲關羽，功效淺薄，未報萬一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-048-89', 'p0131', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '漢王亦馮帝王之號，率巴、漢之民，乘危騁變，結壘千里，志報關羽之敗，圖收湘西之地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-051-90', 'p0131', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '」禽關羽，定荊州，皎有力焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-051-91', 'p0131', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '從討關羽於華容，誘羽餘黨，得五千人，牛馬器械甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-92', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '後從討關羽，封宣城侯，以綏南將軍代呂蒙領南郡太守，住公安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-93', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '劉備東伐吳，吳王求和，瑾與備牋曰：「奄聞旗鼓來至白帝，或恐議臣以吳王侵取此州，危害關羽，怨深禍大，不宜荅和，此用心於小，未留意於大者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-94', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '陛下以關羽之親何如先帝？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-052-95', 'p0131', 'sanguozhi', 'a04-052', '《三國志·吳書七》', '」臣松之云：以為劉后以庸蜀為關河，荊楚為維翰，關羽揚兵沔、漢，志陵上國，雖匡主定霸，功未可必，要為威聲遠震，有其經略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-96', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '備詣京見權，瑜上疏曰：「劉備以梟雄之姿，而有關羽、張飛熊虎之將，必非乆屈為人用者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-97', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」後備西圖璋，留關羽守，權曰：「猾虜乃敢挾詐！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-98', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '酒酣，蒙問肅曰：「君受重任，與關羽為鄰，將何計略，以備不虞？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-99', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」蒙曰：「今東西雖為一家，而關羽實熊虎也，計安可不豫定？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-100', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '兄今代公瑾，旣難為繼，且與關羽為鄰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-101', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '是時劉備令關羽鎮守，專有荊土，權命蒙西取長沙、零、桂三郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-102', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '關羽在南郡，今至尊身自臨之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-103', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '與關羽分土接境，知羽驍雄，有并兼心，且居國上流，其勢難乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-054-104', 'p0131', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '呂蒙勇而有謀斷，識軍計，譎郝普，禽關羽，最其妙者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-105', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權討關羽，欽督水軍入沔，還，道病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-106', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後權破關羽，欲進圖蜀，拜泰漢中太守、奮威將軍，封陵陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-107', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '後隨魯肅鎮益陽，拒關羽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-108', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '羽聞之，住不渡，而結柴營，今遂名此處為關羽瀨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-055-109', 'p0131', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '權征關羽，璋與朱然斷羽走道，到臨沮，住夾石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-056-110', 'p0131', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '建安二十四年，從討關羽，別與潘璋到臨沮禽羽，遷昭武將軍，封西安鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-056-111', 'p0131', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '權討關羽，過範館，謂曰：「昔早從卿言，無此勞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-057-112', 'p0131', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '呂蒙圖取關羽，稱疾還建業，以翻兼知醫術，請以自隨，亦欲因此令翻得釋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-057-113', 'p0131', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '關羽旣敗，權使翻筮之，得兌下坎上，節，五爻變之臨，翻曰：「不出二日，必當斷頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-058-114', 'p0131', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '呂蒙稱疾詣建業，遜往見之，謂曰：「關羽接境，如何遠下，後不當可憂也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-058-115', 'p0131', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '永安二年，拜鎮軍將軍，都督西陵，自關羽至白帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-060-116', 'p0131', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '建安二十四年，劉備將關羽圍樊、襄陽，琮上疏陳羽可討之計，權時已與呂蒙陰議襲之，恐事泄，故寢琮表不荅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-060-117', 'p0131', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '安成長吳碭及中郎將袁龍等首尾關羽，復為反亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-061-118', 'p0131', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '孫權殺關羽，并荊土，拜濬輔軍中郎將，授以兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-062-119', 'p0131', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '呂蒙圖襲關羽，權以問儀，儀善其計，勸權聽之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a04-063-120', 'p0131', 'sanguozhi', 'a04-063', '《三國志·吳書十八》', '權與呂蒙謀襲關羽，議之近臣，多曰不可。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a05-001-121', 'p0131', 'jinshu', 'a05-001', '《晉書·卷一》', '及蜀將關羽圍曹仁於樊，于禁等七軍皆沒，脩、方果降羽，而仁圍甚急焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a05-001-122', 'p0131', 'jinshu', 'a05-001', '《晉書·卷一》', '關羽新破，諸為惡者藏竄觀望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0131-a05-001-123', 'p0131', 'jinshu', 'a05-001', '《晉書·卷一》', '帝曰：「孫權新破關羽，此其欲自結之時也，必不敢為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a03-009-0', 'p0132', 'houhanshu', 'a03-009', '《後漢書·卷九》', '燕剽勇，軍中號曰張飛燕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-001-1', 'p0132', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉備遣張飛、馬超、吳蘭等屯下辯；遣曹洪拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-001-2', 'p0132', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '三月，張飛、馬超走漢中，陰平氐強端斬吳蘭，傳其首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0132-a04-003-3', 'p0132', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '及劉備走小沛，張飛隨之，過謂宜祿曰：「人取汝妻，而為之長，何蚩蚩若是邪！');
